import os
import csv
from datetime import datetime, timedelta

reference_date = datetime(2025, 8, 12)
log_dir = '/app/logs'
output_file = '/app/summary.csv'

severities = ['ERROR', 'WARNING', 'INFO']
periods = [
    ('today', reference_date, reference_date),
    ('last_7_days', reference_date - timedelta(days=6), reference_date),
    ('last_30_days', reference_date - timedelta(days=29), reference_date),
    ('month_to_date', datetime(reference_date.year, reference_date.month, 1), reference_date),
    ('total', None, None)
]

# Initialize counts
counts = {period_name: {sev: 0 for sev in severities} for period_name, _, _ in periods}

if not os.path.exists(log_dir):
    print(f"Error: {log_dir} does not exist.")
    exit(1)

for filename in os.listdir(log_dir):
    if filename.endswith('.log'):
        try:
            # Filename format: YYYY-MM-DD_<source>.log
            date_str = filename.split('_')[0]
            file_date = datetime.strptime(date_str, '%Y-%m-%d')
        except (ValueError, IndexError):
            continue

        filepath = os.path.join(log_dir, filename)
        try:
            with open(filepath, 'r') as f:
                for line in f:
                    found_sev = None
                    if '[ERROR]' in line:
                        found_sev = 'ERROR'
                    elif '[WARNING]' in line:
                        found_sev = 'WARNING'
                    elif '[INFO]' in line:
                        found_sev = 'INFO'

                    if found_sev:
                        for period_name, start, end in periods:
                            if period_name == 'total':
                                counts[period_name][found_sev] += 1
                            elif start <= file_date <= end:
                                counts[period_name][found_sev] += 1
        except Exception as e:
            print(f"Error reading {filename}: {e}")

with open(output_file, 'w', newline='') as csvfile:
    writer = csv.writer(csvfile)
    writer.writerow(['period', 'severity', 'count'])
    for period_name, _, _ in periods:
        for sev in severities:
            writer.writerow([period_name, sev, counts[period_name][sev]])

print("Analysis complete. Output saved to", output_file)
EOF
